def find_beautiful_string(n, k, s):
    # Check if it's possible to create a beautiful string
    for i in range(n - k + 1):
        if s[i] != s[i + k - 1]:
            break
    else:
        # All substrings of length k are the same
        return 'YES', ''.join(s[:k])

    # Try to find the lexicographically smallest beautiful string
    for i in range(k):
        for bit in '01':
            if all(s[j] == bit or s[j + k] == bit for j in range(i, n - k + 1, k)):
                return 'YES', '1' * i + bit + '0' * (k - i - 1)
    return 'NO', ''

